"""Detect damaged audio tracks that cause subtitle timeline drift.

Some downloaded video files hide gaps in the audio packet timeline: players
fill them with silence, but a naive demux/join collapses the gap and every
later subtitle lands early by the hole's length.

This module only measures and describes. Repair (silence fill via
``aresample=async=1``) lives in ``preprocess.stabilize_media_timeline``.
"""

from __future__ import annotations

import json
import logging
import subprocess
import threading
import time
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Sequence

_log = logging.getLogger("transub_engine.audio.integrity")

# Thresholds prefer missing a problem over false alarms.
GAP_WARN_S = 0.5
BACKWARDS_WARN_S = 0.5
LENGTH_WARN_S = 1.0
AV_LENGTH_WARN_S = 3.0
DECODE_ERROR_LINES_WARN = 1
MAX_PLACES = 5


@dataclass
class IntegrityFinding:
    kind: str  # no_audio | hole | backwards | length | av_length | decode_errors
    detail: str
    at_s: float | None = None
    size_s: float = 0.0

    def to_dict(self) -> dict[str, Any]:
        return {
            "kind": self.kind,
            "detail": self.detail,
            "atSec": self.at_s,
            "sizeSec": self.size_s,
        }


@dataclass
class IntegrityReport:
    findings: list[IntegrityFinding] = field(default_factory=list)
    facts: dict[str, Any] = field(default_factory=dict)
    seconds: float = 0.0
    checked: bool = True

    @property
    def suspect(self) -> bool:
        return bool(self.findings)

    def summary(self) -> str:
        if not self.findings:
            return ""
        return "audio integrity: " + "; ".join(f.detail for f in self.findings)

    def to_dict(self) -> dict[str, Any]:
        return {
            "checked": self.checked,
            "suspect": self.suspect,
            "seconds": self.seconds,
            "summary": self.summary(),
            "findings": [f.to_dict() for f in self.findings],
            "facts": dict(self.facts),
        }


def hms(seconds: float) -> str:
    s = int(round(float(seconds)))
    return f"{s // 3600}:{s % 3600 // 60:02d}:{s % 60:02d}"


def _num(x: Any) -> float | None:
    try:
        return float(x)
    except (TypeError, ValueError):
        return None


def find_timeline_breaks(
    pts: Sequence[float],
    dur: Sequence[float],
    *,
    gap_warn_s: float = GAP_WARN_S,
    backwards_warn_s: float = BACKWARDS_WARN_S,
) -> list[IntegrityFinding]:
    """Find holes and backwards jumps in an audio packet timeline (seconds)."""
    n = min(len(pts), len(dur))
    if n == 0:
        return []
    typical = sorted(dur[:n])[n // 2]
    holes: list[tuple[float, float]] = []
    backwards: list[tuple[float, float]] = []
    for i in range(n):
        hidden = float(dur[i]) - float(typical)
        if hidden >= gap_warn_s:
            holes.append((float(pts[i]) + float(typical), hidden))
        if i + 1 < n:
            step = float(pts[i + 1]) - (float(pts[i]) + float(dur[i]))
            if step >= gap_warn_s:
                holes.append((float(pts[i]) + float(dur[i]), step))
            elif float(pts[i + 1]) <= float(pts[i]) - backwards_warn_s:
                backwards.append((float(pts[i + 1]), float(pts[i]) - float(pts[i + 1])))
    out: list[IntegrityFinding] = []
    if holes:
        total = sum(h for _, h in holes)
        places = ", ".join(f"{h:.1f} s @ {hms(t)}" for t, h in holes[:MAX_PLACES])
        more = f" and {len(holes) - MAX_PLACES} more" if len(holes) > MAX_PLACES else ""
        out.append(
            IntegrityFinding(
                "hole",
                f"{len(holes)} gap(s) in the audio track, {total:.1f} s total ({places}{more})",
                at_s=holes[0][0],
                size_s=total,
            )
        )
    if backwards:
        places = ", ".join(f"{b:.1f} s @ {hms(t)}" for t, b in backwards[:MAX_PLACES])
        more = f" and {len(backwards) - MAX_PLACES} more" if len(backwards) > MAX_PLACES else ""
        out.append(
            IntegrityFinding(
                "backwards",
                f"audio timestamps run backwards {len(backwards)} time(s) ({places}{more})",
                at_s=backwards[0][0],
                size_s=max(b for _, b in backwards),
            )
        )
    return out


def track_timeline_s(pts: Sequence[float], dur: Sequence[float]) -> float | None:
    n = min(len(pts), len(dur))
    if n == 0:
        return None
    return max(p + d for p, d in zip(pts[:n], dur[:n])) - min(pts[:n])


def count_decode_errors(ffmpeg_stderr: str) -> int:
    return sum(
        1
        for line in (ffmpeg_stderr or "").splitlines()
        if "[error]" in line or "[fatal]" in line
    )


def assess(
    facts: dict[str, Any],
    pts: Sequence[float] = (),
    dur: Sequence[float] = (),
    extracted_s: float | None = None,
    decode_error_lines: int = 0,
) -> list[IntegrityFinding]:
    findings: list[IntegrityFinding] = []
    if facts.get("n_audio") == 0:
        return [IntegrityFinding("no_audio", "media has no audio track")]

    findings += find_timeline_breaks(pts, dur)
    holes_s = sum(f.size_s for f in findings if f.kind == "hole")

    timeline = track_timeline_s(pts, dur)
    if timeline is None:
        timeline = facts.get("audio_dur") or facts.get("format_dur")
    if extracted_s is not None and timeline:
        diff = float(extracted_s) - float(timeline)
        explained = holes_s > 0 and diff < 0 and abs(-diff - holes_s) < LENGTH_WARN_S
        if abs(diff) >= LENGTH_WARN_S and not explained:
            word = "shorter" if diff < 0 else "longer"
            findings.append(
                IntegrityFinding(
                    "length",
                    f"extracted audio is {abs(diff):.1f} s {word} than the track timeline "
                    f"({float(extracted_s):.1f} s vs {float(timeline):.1f} s)",
                    size_s=abs(diff),
                )
            )

    audio_len = facts.get("audio_dur") or timeline
    video_len = facts.get("video_dur") or (
        facts.get("format_dur") if facts.get("has_video") else None
    )
    if audio_len and video_len and float(video_len) - float(audio_len) >= AV_LENGTH_WARN_S:
        gap = float(video_len) - float(audio_len)
        findings.append(
            IntegrityFinding(
                "av_length",
                f"audio ends {gap:.1f} s before video ({hms(float(audio_len))} vs {hms(float(video_len))})",
                at_s=float(audio_len),
                size_s=gap,
            )
        )

    if decode_error_lines >= DECODE_ERROR_LINES_WARN:
        findings.append(
            IntegrityFinding(
                "decode_errors",
                f"FFmpeg reported {decode_error_lines} error line(s) while decoding audio",
                size_s=0.0,
            )
        )
    return findings


def _run_ffprobe(ffprobe: str, args: list[str]) -> subprocess.CompletedProcess[str]:
    run_kwargs: dict[str, Any] = {
        "capture_output": True,
        "text": True,
        "encoding": "utf-8",
        "errors": "replace",
        "check": False,
    }
    import os

    if os.name == "nt":
        run_kwargs["creationflags"] = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    return subprocess.run([ffprobe, *args], **run_kwargs)


def read_stream_facts(ffprobe: str, media: str | Path) -> dict[str, Any]:
    proc = _run_ffprobe(
        ffprobe,
        [
            "-v",
            "error",
            "-show_entries",
            "stream=codec_type,start_time,duration:format=duration",
            "-of",
            "json",
            str(media),
        ],
    )
    if proc.returncode != 0:
        raise RuntimeError((proc.stderr or proc.stdout or "ffprobe failed").strip()[:400])
    data = json.loads(proc.stdout or "{}")
    streams = data.get("streams") or []
    audio = [s for s in streams if s.get("codec_type") == "audio"]
    video = [s for s in streams if s.get("codec_type") == "video"]
    a0 = audio[0] if audio else {}
    v0 = video[0] if video else {}
    return {
        "n_audio": len(audio),
        "has_video": bool(video),
        "audio_start": _num(a0.get("start_time")),
        "video_start": _num(v0.get("start_time")),
        "audio_dur": _num(a0.get("duration")),
        "video_dur": _num(v0.get("duration")),
        "format_dur": _num((data.get("format") or {}).get("duration")),
    }


def read_audio_packets(ffprobe: str, media: str | Path) -> tuple[list[float], list[float]]:
    proc = _run_ffprobe(
        ffprobe,
        [
            "-v",
            "error",
            "-select_streams",
            "a:0",
            "-show_entries",
            "packet=pts_time,duration_time,flags",
            "-of",
            "csv=p=0",
            str(media),
        ],
    )
    if proc.returncode != 0:
        raise RuntimeError((proc.stderr or proc.stdout or "ffprobe packets failed").strip()[:400])
    pts: list[float] = []
    dur: list[float] = []
    for line in (proc.stdout or "").splitlines():
        parts = line.split(",")
        if len(parts) < 2 or (len(parts) > 2 and "D" in parts[2]):
            continue
        p, q = _num(parts[0]), _num(parts[1])
        if p is not None and q is not None:
            pts.append(p)
            dur.append(q)
    return pts, dur


def _read_media(ffprobe: str, media: str | Path) -> tuple[dict[str, Any], list[float], list[float]]:
    facts = read_stream_facts(ffprobe, media)
    pts, dur = read_audio_packets(ffprobe, media) if facts.get("n_audio") else ([], [])
    return facts, pts, dur


class IntegrityProbe:
    """Overlap packet probing with timeline stabilization (same idea as WhisperJAV 1.9.4)."""

    def __init__(self, ffprobe: str | None, media: str | Path):
        self.media = media
        self._started = time.monotonic()
        self._result: tuple[dict[str, Any], list[float], list[float]] | None = None
        self._error: str | None = None if ffprobe else "ffprobe not found"
        self._thread: threading.Thread | None = None
        if ffprobe:
            self._thread = threading.Thread(
                target=self._read,
                args=(ffprobe,),
                daemon=True,
                name="transub-audio-integrity",
            )
            self._thread.start()

    def _read(self, ffprobe: str) -> None:
        try:
            self._result = _read_media(ffprobe, self.media)
        except Exception as exc:  # noqa: BLE001 ? never fail the job for a check
            self._error = str(exc) or type(exc).__name__

    def finish(
        self,
        extracted_s: float | None,
        extraction_stderr: str = "",
    ) -> IntegrityReport:
        self._started = time.monotonic()
        if self._thread is not None:
            self._thread.join()
        report = IntegrityReport()
        if self._result is None:
            report.checked = False
            report.facts["not_checked"] = self._error or "no result"
            _log.debug("audio integrity skipped for %s: %s", self.media, report.facts["not_checked"])
        else:
            try:
                facts, pts, dur = self._result
                errors = count_decode_errors(extraction_stderr)
                facts.update(
                    packets=len(pts),
                    track_timeline_s=track_timeline_s(pts, dur),
                    extracted_s=extracted_s,
                    decode_error_lines=errors,
                )
                report.facts = facts
                report.findings = assess(facts, pts, dur, extracted_s, errors)
            except Exception as exc:  # noqa: BLE001
                report.checked = False
                report.facts["not_checked"] = str(exc) or type(exc).__name__
        report.seconds = round(time.monotonic() - self._started, 2)
        return report


def console_message(report: IntegrityReport, media_name: str, *, repaired: bool = True) -> str:
    if not report.checked:
        return f"????????{report.facts.get('not_checked', 'unknown')}?"
    if not report.suspect:
        return f"???????{report.seconds:.1f}s?"
    hole = next((f for f in report.findings if f.kind == "hole"), None)
    others = [f.detail for f in report.findings if f is not hole]
    if hole is not None:
        text = f"?????{media_name}??" + hole.detail.replace(" in the audio track", "", 1)
        if others:
            text += "?" + "?".join(others)
        if repaired:
            text += "???????????????????????????"
        else:
            text += "????????????????"
    else:
        text = f"?????{media_name}??" + "?".join(others) + "?"
        if repaired:
            text += "????????????????"
    return text


def wav_duration_s(path: str | Path) -> float | None:
    """Read duration from a WAV/container header via ffprobe when available."""
    from ..ffmpeg_util import resolve_ffprobe

    ffprobe = resolve_ffprobe()
    if not ffprobe:
        try:
            import soundfile as sf

            info = sf.info(str(path))
            if info.samplerate > 0 and info.frames > 0:
                return float(info.frames) / float(info.samplerate)
        except Exception:
            return None
        return None
    proc = _run_ffprobe(
        ffprobe,
        [
            "-v",
            "error",
            "-show_entries",
            "format=duration",
            "-of",
            "default=noprint_wrappers=1:nokey=1",
            str(path),
        ],
    )
    if proc.returncode != 0:
        return None
    return _num((proc.stdout or "").strip())
